/// Cox-Ross-Rubinstein tree; at each node the holder takes the larger of continuation
/// and immediate exercise.
inline double american_binomial(double S0, double K, double r, double sigma, double T, long long steps, bool is_call) {
    if (steps < 1) {
        throw qt::ValueError("steps must be at least 1");
    }
    double dt = qt::py::truediv(T, static_cast<double>(steps));
    double u = qt::npm::exp(sigma * std::sqrt(dt));
    double d = 1.0 / u;
    double p = (qt::npm::exp(r * dt) - d) / (u - d);
    if (!(0 < p && p < 1)) {
        // outside (0, 1) the tree admits arbitrage and values grow like p^steps: refuse
        throw qt::ValueError("risk-neutral probability outside (0, 1): use more steps");
    }
    double disc = qt::npm::exp(-r * dt);
    qt::IVec j = qt::iarange(qt::iadd(steps, 1LL));
    qt::Vec S = qt::broadcast(S0 * qt::pow(u, j.cast<double>()), qt::pow(d, qt::isub(steps, j).cast<double>()), qt::mul_op{});  // terminal stock prices, lowest first
    qt::Vec V = is_call ? qt::Vec(qt::maximum(S - K, 0.0)) : qt::Vec(qt::maximum(K - S, 0.0));
    for (long long _ = 0; _ < steps; ++_) {
        S = (qt::slice(S, qt::none, -1) / d).eval();  // one step back: node j had price S_j(n) / d
        qt::Vec cont = disc * (p * qt::slice(V, 1, qt::none) + (1 - p) * qt::slice(V, qt::none, -1));
        qt::Vec exercise = is_call ? qt::Vec(S - K) : qt::Vec(K - S);
        V = qt::maximum(cont, exercise);
    }
    return V(0);
}

/// American minus European put on the same tree.
inline double early_exercise_premium(double S0, double K, double r, double sigma, double T, long long steps) {
    double dt = qt::py::truediv(T, static_cast<double>(steps));
    double u = qt::npm::exp(sigma * std::sqrt(dt));
    double d = 1.0 / u;
    double p = (qt::npm::exp(r * dt) - d) / (u - d);
    if (!(0 < p && p < 1)) {
        throw qt::ValueError("risk-neutral probability outside (0, 1): use more steps");
    }
    double disc = qt::npm::exp(-r * dt);
    qt::IVec j = qt::iarange(qt::iadd(steps, 1LL));
    qt::Vec V = qt::maximum(K - qt::broadcast(S0 * qt::pow(u, j.cast<double>()), qt::pow(d, qt::isub(steps, j).cast<double>()), qt::mul_op{}), 0.0);
    for (long long _ = 0; _ < steps; ++_) {
        V = (disc * (p * qt::slice(V, 1, qt::none) + (1 - p) * qt::slice(V, qt::none, -1))).eval();
    }
    return american_binomial(S0, K, r, sigma, T, steps) - V(0);
}

/// European option values at t = 0 on the grid S_i = i * S_max / n_s, by explicit
/// finite differences backwards from the payoff. Stable when dt < 1 / (sigma^2 n_s^2).
inline qt::Vec bs_explicit_fd(double K, double r, double sigma, double T, double S_max, long long n_s, long long n_t, bool is_call) {
    double dt = qt::py::truediv(T, static_cast<double>(n_t));
    qt::Vec S = qt::linspace(0.0, S_max, qt::iadd(n_s, 1LL));
    qt::Vec V = is_call ? qt::Vec(qt::maximum(S - K, 0.0)) : qt::Vec(qt::maximum(K - S, 0.0));
    qt::IVec i = qt::iarange(1LL, n_s);
    qt::Vec a = 0.5 * dt * qt::broadcast(qt::py::power(sigma, 2.0) * qt::ipow(i, 2LL).cast<double>(), r * i.cast<double>(), qt::sub_op{});
    qt::Vec b = 1.0 - dt * (qt::py::power(sigma, 2.0) * qt::ipow(i, 2LL).cast<double>() + r);
    qt::Vec c = 0.5 * dt * qt::broadcast(qt::py::power(sigma, 2.0) * qt::ipow(i, 2LL).cast<double>(), r * i.cast<double>(), qt::add_op{});
    for (long long k = 1; k < qt::iadd(n_t, 1LL); ++k) {
        double tau = static_cast<double>(k) * dt;
        qt::store(qt::slice(V, 1, -1), (qt::broadcast(qt::broadcast(qt::broadcast(a, qt::slice(V, qt::none, -2), qt::mul_op{}), qt::broadcast(b, qt::slice(V, 1, -1), qt::mul_op{}), qt::add_op{}), qt::broadcast(c, qt::slice(V, 2, qt::none), qt::mul_op{}), qt::add_op{})).eval());  // every interior node from the old values
        if (is_call) {
            V(0) = 0.0;
            V(V.size() - 1) = S_max - K * qt::npm::exp(-r * tau);
        } else {
            V(0) = K * qt::npm::exp(-r * tau);
            V(V.size() - 1) = 0.0;
        }
    }
    return V;
}

/// Price at S0, interpolating linearly between grid nodes.
inline double fd_price(double S0, double K, double r, double sigma, double T, double S_max, long long n_s, long long n_t, bool is_call) {
    qt::Vec V = bs_explicit_fd(K, r, sigma, T, S_max, n_s, n_t, is_call);
    double dS = qt::py::truediv(S_max, static_cast<double>(n_s));
    long long i = qt::to_int(qt::floordiv(S0, dS));
    if (i < 0 || i >= n_s) {
        throw qt::ValueError("S0 must lie inside the grid");
    }
    double w = qt::py::truediv(S0 - static_cast<double>(i) * dS, dS);
    const double left = (1 - w) * V(qt::idx(i, V.size()));
    return left + w * V(qt::idx(qt::iadd(i, 1LL), V.size()));
}

